import type { RouteHandler } from "../types.js";
import { sendJson, sendError } from "../response.js";

/**
 * GET /api/v1/alerts
 * Retrieves alerts generated by the keeper with optional filters and bounded pagination.
 */
export const alertsHandler: RouteHandler = (_req, res, url, ctx) => {
  const params = url.searchParams;

  // Validate watchlistId
  let watchlistId: number | undefined;
  if (params.has("watchlistId")) {
    const rawId = Number(params.get("watchlistId"));
    if (!Number.isInteger(rawId) || rawId < 1) {
      return sendError(
        res,
        400,
        "INVALID_PARAMETER",
        "watchlistId must be a positive integer",
        ctx.corsOrigin,
      );
    }
    watchlistId = rawId;
  }

  // Validate network
  const network = params.get("network") || undefined;
  if (network && network !== "testnet" && network !== "mainnet") {
    return sendError(
      res,
      400,
      "INVALID_PARAMETER",
      "Network must be 'testnet' or 'mainnet'",
      ctx.corsOrigin,
    );
  }

  // Validate category (including unknown_status)
  const category = params.get("category") || undefined;
  const validCategories = [
    "low_ttl",
    "ttl_reached",
    "unknown_status",
    "rpc_failure",
    "config_failure",
  ];
  if (category && !validCategories.includes(category)) {
    return sendError(
      res,
      400,
      "INVALID_PARAMETER",
      `category must be one of: ${validCategories.join(", ")}`,
      ctx.corsOrigin,
    );
  }

  // Validate deliveryStatus
  const deliveryStatus = params.get("deliveryStatus") || undefined;
  if (deliveryStatus && !["pending", "delivered", "failed"].includes(deliveryStatus)) {
    return sendError(
      res,
      400,
      "INVALID_PARAMETER",
      "deliveryStatus must be one of: 'pending', 'delivered', 'failed'",
      ctx.corsOrigin,
    );
  }

  // Validate pagination
  let limit = 50;
  if (params.has("limit")) {
    const rawLimit = Number(params.get("limit"));
    if (!Number.isInteger(rawLimit) || rawLimit < 1 || rawLimit > 100) {
      return sendError(
        res,
        400,
        "INVALID_PARAMETER",
        "limit must be an integer between 1 and 100",
        ctx.corsOrigin,
      );
    }
    limit = rawLimit;
  }

  let offset = 0;
  if (params.has("offset")) {
    const rawOffset = Number(params.get("offset"));
    if (!Number.isInteger(rawOffset) || rawOffset < 0) {
      return sendError(
        res,
        400,
        "INVALID_PARAMETER",
        "offset must be a non-negative integer",
        ctx.corsOrigin,
      );
    }
    offset = rawOffset;
  }

  try {
    const alerts = ctx.db.listAlerts({
      ...(watchlistId !== undefined ? { watchlistId } : {}),
      network: network ?? ctx.network,
      ...(category !== undefined ? { category } : {}),
      ...(deliveryStatus !== undefined ? { deliveryStatus } : {}),
      limit,
      offset,
    });

    sendJson(
      res,
      200,
      {
        success: true,
        data: alerts,
        pagination: {
          limit,
          offset,
          returned: alerts.length,
        },
        timestamp: new Date().toISOString(),
      },
      ctx.corsOrigin,
    );
  } catch (err) {
    ctx.logger.error({ err }, "Database error in /api/v1/alerts");
    sendError(res, 500, "INTERNAL_ERROR", "Failed to retrieve alerts", ctx.corsOrigin);
  }
};
